class NursingCarePlanService:
    @staticmethod
    def get_care_plan(code: str) -> Optional[NursingCarePlan]:
        return NURSING_CARE_PLANS_DATABASE.get(code.strip())

    @staticmethod
    def search_by_domain(domain: str) -> List[NursingCarePlan]:
        return [p for p in NURSING_CARE_PLANS_DATABASE.values() if p.domain.lower() == domain.lower()]
